from collections import deque

def resolve(path, cwd, links):
    if path is None:
        return None

    # Determine starting point
    if path.startswith('/'):
        current = '/'
    else:
        current = cwd

    components = deque(path.split('/'))
    link_count = 0

    while components:
        comp = components.popleft()
        if comp == '' or comp == '.':
            continue
        elif comp == '..':
            if current != '/':
                idx = current.rfind('/')
                if idx <= 0:
                    current = '/'
                else:
                    current = current[:idx]
        else:
            if current == '/':
                candidate = '/' + comp
            else:
                candidate = current + '/' + comp

            if candidate in links:
                link_count += 1
                if link_count > 8:
                    return None
                target = links[candidate]
                if target.startswith('/'):
                    current = '/'
                    components = deque(target.split('/')) + components
                else:
                    # relative to directory containing the link (i.e., 'current' before appending comp)
                    components = deque(target.split('/')) + components
                    # current remains unchanged
            else:
                current = candidate

    return current

